// Analytics service client.
//
// In a real app this would POST to your analytics backend. It is kept as a
// standalone module so it can be mocked in tests and reused across routes.

export type PageView = {
  path: string
  userAgent: string
  timestamp: string
}

export async function logPageView(view: PageView): Promise<void> {
  // Replace with your real analytics endpoint.
  const res = await fetch('https://example.com/analytics', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(view),
    // `keepalive` lets the request outlive the current request lifecycle,
    // which pairs well with `after` for fire-and-forget analytics.
    keepalive: true,
  })

  if (!res.ok) {
    console.error('[analytics] failed to log page view', res.status)
  }
}

