import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from './analytics'

export default async function Home() {
  // Read request data during the render lifecycle. In a Server Component,
  // request-time APIs like `headers()` cannot be called inside `after`,
  // so we read them here and pass the values in via closure.
  const headerList = await headers()
  const userAgent = headerList.get('user-agent') || 'unknown'

  // Schedule the analytics call to run after the response is sent so it
  // does not block the response. See:
  // https://nextjs.org/docs/app/api-reference/functions/after
  after(() => {
    logPageView({
      path: '/',
      userAgent,
      timestamp: new Date().toISOString(),
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>This page view has been logged to our analytics service.</p>
    </main>
  )
}

